static inline void wr_aby(uint8_t tmp)
{
	ea_aby();
	wb_ea(tmp);
}

static inline void wr_zpi(uint8_t tmp)
{
	ea_zpi();
	wb_ea(tmp);
}

static inline void wr_idx(uint8_t tmp)
{
	ea_idx();
	wb_ea(tmp);
}

static inline void wr_idy(uint8_t tmp)
{
	ea_idy();
	wb_ea(tmp);
}

static inline void wb_ea(uint8_t tmp)
{
	program_write8(EAD, tmp);
}

static inline void wb_eaz(uint8_t tmp)
{
	program_write8z(EAD, tmp);
}

/***************************************************************
 *
 * Macros to emulate the 6280 opcodes
 *
 ***************************************************************/

/***************************************************************
 * compose the real flag register by
 * including N and Z and set any
 * SET and clear any CLR bits also
 ***************************************************************/
#if H6280_LAZY_FLAGS

static inline void compose_p(uint8_t SET, uint8_t CLR)
{
	P = (P & ~(_fN | _fZ | CLR)) |
		(NZ >> 8) |
		((NZ & 0xff) ? 0 : _fZ) |
		SET;
}

#else

static inline void compose_p(uint8_t SET, uint8_t CLR)
{
	P = (P & ~CLR) | SET;
}

#endif

/* 6280 ********************************************************
 *  ADC Add with carry
 ***************************************************************/
static inline void tadc(uint8_t tmp)
{
	clear_t();
	int tflagtemp = rd_tfl();
	if (P & _fD)
	{
		int c = (P & _fC);
		int lo = (tflagtemp & 0x0f) + (tmp & 0x0f) + c;
		int hi = (tflagtemp & 0xf0) + (tmp & 0xf0);
		P &= ~_fC;
		if (lo > 0x09)
		{
			hi += 0x10;
			lo += 0x06;
		}
		if (hi > 0x90)
			hi += 0x60;
		if (hi & 0xff00)
			P |= _fC;
		tflagtemp = (lo & 0x0f) + (hi & 0xf0);
		h6280_cycles(1);
	}
	else
	{
		int c = (P & _fC);
		int sum = tflagtemp + tmp + c;
		P &= ~(_fV | _fC);
		if (~(tflagtemp^tmp) & (tflagtemp^sum) & _fN)
			P |= _fV;
		if (sum & 0xff00)
			P |= _fC;
		tflagtemp = (uint8_t) sum;
	}
	set_nz(tflagtemp);
	wb_eaz(tflagtemp);
	h6280_cycles(3);
}


static inline void adc(uint8_t tmp)
{
	if(P & _fT)
		tadc(tmp);
	else {
		if (P & _fD)
		{
			int c = (P & _fC);
			int lo = (A & 0x0f) + (tmp & 0x0f) + c;
			int hi = (A & 0xf0) + (tmp & 0xf0);
			P &= ~_fC;
			if (lo > 0x09)
			{
				hi += 0x10;
				lo += 0x06;
			}
			if (hi > 0x90)
				hi += 0x60;
			if (hi & 0xff00)
				P |= _fC;
			A = (lo & 0x0f) + (hi & 0xf0);
			h6280_cycles(1);
		}
		else
		{
			int c = (P & _fC);
			int sum = A + tmp + c;
			P &= ~(_fV | _fC);
			if (~(A^tmp) & (A^sum) & _fN)
				P |= _fV;
			if (sum & 0xff00)
				P |= _fC;
			A = (uint8_t) sum;
		}
		set_nz(A);
	}
}

/* 6280 ********************************************************
 *  AND Logical and
 ***************************************************************/
static inline void tand(uint8_t tmp)
{
	clear_t();
	int tflagtemp = rd_tfl();
	tflagtemp = (uint8_t)(tflagtemp & tmp);
	wb_eaz(tflagtemp);
	set_nz(tflagtemp);
	h6280_cycles(3);
}

static inline void and_a(uint8_t tmp)
{
	if(P & _fT)
		tand(tmp);
	else {
		A = (uint8_t)(A & tmp);
		set_nz(A);
	}
}

/* 6280 ********************************************************
 *  ASL Arithmetic shift left
 ***************************************************************/
static inline uint8_t asl(uint8_t tmp)
{
	clear_t();
	P = (P & ~_fC) | ((tmp >> 7) & _fC);
	tmp = (uint8_t)(tmp << 1);
	set_nz(tmp);
	return tmp;
}

/* 6280 ********************************************************
 *  BBR Branch if bit is reset
 ***************************************************************/
static inline void bbr(int bit, uint8_t tmp)
{
	bra(!(tmp & (1<<bit)));
}

/* 6280 ********************************************************
 *  BBS Branch if bit is set
 ***************************************************************/
static inline void bbs(int bit, uint8_t tmp)
{
	bra(tmp & (1<<bit));
}

/* 6280 ********************************************************
 *  BCC Branch if carry clear
 ***************************************************************/
static inline void bcc(void)
{
	bra(!(P & _fC));
}

/* 6280 ********************************************************
 *  BCS Branch if carry set
 ***************************************************************/
static inline void bcs(void)
{
	bra(P & _fC);
}

/* 6280 ********************************************************
 *  BEQ Branch if equal
 ***************************************************************/
static inline void beq(void)
{
#if H6280_LAZY_FLAGS
	bra(!(NZ & 0xff));
#else
	bra(P & _fZ);
#endif
}

/* 6280 ********************************************************
 *  BIT Bit test
 ***************************************************************/
static inline void bit(uint8_t tmp)
{
	P = (P & ~(_fN|_fV|_fT|_fZ))
		| ((tmp&0x80) ? _fN:0)
		| ((tmp&0x40) ? _fV:0)
		| ((tmp&A)  ? 0:_fZ);
}

/* 6280 ********************************************************
 *  BMI Branch if minus
 ***************************************************************/
static inline void bmi(void)
{
#if H6280_LAZY_FLAGS
	bra(NZ & 0x8000);
#else
	bra(P & _fN);
#endif
}

/* 6280 ********************************************************
 *  BNE Branch if not equal
 ***************************************************************/
static inline void bne(void)
{
#if H6280_LAZY_FLAGS
	bra(NZ & 0xff);
#else
	bra(!(P & _fZ));
#endif
}

/* 6280 ********************************************************
 *  BPL Branch if plus
 ***************************************************************/
static inline void bpl(void)
{
#if H6280_LAZY_FLAGS
	bra(!(NZ & 0x8000));
#else
	bra(!(P & _fN));
#endif
}

/* 6280 ********************************************************
 *  BRK Break
 *  increment PC, push PC hi, PC lo, flags (with B bit set),
 *  set I flag, reset D flag and jump via IRQ vector
 ***************************************************************/
static inline void brk(void)
{
	
	clear_t();
	PCW++;
	push(PCH);
	push(PCL);
	push(P);
	P = (P & ~_fD) | _fI;
	PCL = program_read8(H6280_IRQ2_VEC);
	PCH = program_read8(H6280_IRQ2_VEC+1);
}

/* 6280 ********************************************************
 *  BSR Branch to subroutine
 ***************************************************************/
static inline void bsr(void)
{
	push(PCH);
	push(PCL);
	h6280_cycles(4); /* 4 cycles here, 4 in BRA */
	bra(1);
}

/* 6280 ********************************************************
 *  BVC Branch if overflow clear
 ***************************************************************/
static inline void bvc(void)
{
	bra(!(P & _fV));
}

/* 6280 ********************************************************
 *  BVS Branch if overflow set
 ***************************************************************/
static inline void bvs(void)
{
	bra(P & _fV);
}

/* 6280 ********************************************************
 *  CLA Clear accumulator
 ***************************************************************/
static inline void cla(void)
{
	clear_t();
	A = 0;
}

/* 6280 ********************************************************
 *  CLC Clear carry flag
 ***************************************************************/
static inline void clc(void)
{
	clear_t();
	P &= ~_fC;
}

/* 6280 ********************************************************
 *  CLD Clear decimal flag
 ***************************************************************/
static inline void cld(void)
{
	clear_t();
	P &= ~_fD;
}

/* 6280 ********************************************************
 *  CLI Clear interrupt flag
 ***************************************************************/
static inline void cli(void)
{
	clear_t();
	if( P & _fI )
	{
		P &= ~_fI;
		check_irq_lines();
	}
}


/* 6280 ********************************************************
 *  CLV Clear overflow flag
 ***************************************************************/
static inline void clv(void)
{
	clear_t();
	P &= ~_fV;
}

/* 6280 ********************************************************
 *  CLX Clear index X
 ***************************************************************/
static inline void clx(void)
{
	clear_t();
	X = 0;
}

/* 6280 ********************************************************
 *  CLY Clear index Y
 ***************************************************************/
static inline void cly(void)
{
	clear_t();
	Y = 0;
}

/* 6280 ********************************************************
 *  CMP Compare accumulator
 ***************************************************************/
static inline void cmp(uint8_t tmp)
{
	clear_t();
	P &= ~_fC;
	if (A >= tmp)
		P |= _fC;
	set_nz((uint8_t)(A - tmp));
}

/* 6280 ********************************************************
 *  CPX Compare index X
 ***************************************************************/
static inline void cpx(uint8_t tmp)
{
	clear_t();
	P &= ~_fC;
	if (X >= tmp)
		P |= _fC;
	set_nz((uint8_t)(X - tmp));
}

/* 6280 ********************************************************
 *  CPY Compare index Y
 ***************************************************************/
static inline void cpy(uint8_t tmp)
{
	clear_t();
	P &= ~_fC;
	if (Y >= tmp)
		P |= _fC;
	set_nz((uint8_t)(Y - tmp));
}

/* 6280 ********************************************************
 *  DEC Decrement memory
 ***************************************************************/
static inline uint8_t dec(uint8_t tmp)
{
	clear_t();
	tmp = (uint8_t)(tmp-1);
	set_nz(tmp);
	return tmp;
}

/* 6280 ********************************************************
 *  DEX Decrement index X
 ***************************************************************/
static inline void dex(void)
{
	clear_t();
	X = (uint8_t)(X - 1);
	set_nz(X);
}

/* 6280 ********************************************************
 *  DEY Decrement index Y
 ***************************************************************/
static inline void dey(void)
{
	clear_t();
	Y = (uint8_t)(Y - 1);
	set_nz(Y);
}

/* 6280 ********************************************************
 *  EOR Logical exclusive or
 ***************************************************************/
static inline void teor(uint8_t tmp)
{
	clear_t();
	int tflagtemp = rd_tfl();
	tflagtemp = (uint8_t)(tflagtemp ^ tmp);
	wb_eaz(tflagtemp);
	set_nz(tflagtemp);
	h6280_cycles(3);
}

static inline void eor(uint8_t tmp)
{
	if(P & _fT)
		teor(tmp);
	else {
		A = (uint8_t)(A ^ tmp);
		set_nz(A);
	}
}

/* 6280 ********************************************************
 *  INC Increment memory
 ***************************************************************/
static inline uint8_t inc(uint8_t tmp)
{
	clear_t();
	tmp = (uint8_t)(tmp+1);
	set_nz(tmp);
	return tmp;
}

/* 6280 ********************************************************
 *  INX Increment index X
 ***************************************************************/
static inline void inx(void)
{
	clear_t();
	X = (uint8_t)(X + 1);
	set_nz(X);
}

/* 6280 ********************************************************
 *  INY Increment index Y
 ***************************************************************/
static inline void iny(void)
{
	clear_t();
	Y = (uint8_t)(Y + 1);
	set_nz(Y);
}

/* 6280 ********************************************************
 *  JMP Jump to address
 *  set PC to the effective address
 ***************************************************************/
static inline void jmp(void)
{
	clear_t();
	PCD = EAD;
}

/* 6280 ********************************************************
 *  JSR Jump to subroutine
 *  decrement PC (sic!) push PC hi, push PC lo and set
 *  PC to the effective address
 ***************************************************************/
static inline void jsr(void)
{
	clear_t();
	PCW--;
	push(PCH);
	push(PCL);
	PCD = EAD;
}

/* 6280 ********************************************************
 *  LDA Load accumulator
 ***************************************************************/
static inline void lda(uint8_t tmp)
{
	clear_t();
	A = (uint8_t)tmp;
	set_nz(A);
}

/* 6280 ********************************************************
 *  LDX Load index X
 ***************************************************************/
static inline void ldx(uint8_t tmp)
{
	clear_t();
	X = (uint8_t)tmp;
	set_nz(X);
}

/* 6280 ********************************************************
 *  LDY Load index Y
 ***************************************************************/
static inline void ldy(uint8_t tmp)
{
	clear_t();
	Y = (uint8_t)tmp;
	set_nz(Y);
}

/* 6280 ********************************************************
 *  LSR Logic shift right
 *  0 -> [7][6][5][4][3][2][1][0] -> C
 ***************************************************************/
static inline uint8_t lsr(uint8_t tmp)
{
	clear_t();
	P = (P & ~_fC) | (tmp & _fC);
	tmp = (uint8_t)tmp >> 1;
	set_nz(tmp);
	return tmp;
}

/* 6280 ********************************************************
 *  NOP No operation
 ***************************************************************/
static inline void nop(void)
{
	clear_t();
}

/* 6280 ********************************************************
 *  ORA Logical inclusive or
 ***************************************************************/

static inline void tora(uint8_t tmp)
{
	clear_t();
	int tflagtemp = rd_tfl();
	tflagtemp = (uint8_t)(tflagtemp | tmp);
	wb_eaz(tflagtemp);
	set_nz(tflagtemp);
	h6280_cycles(3);
}

static inline void ora(uint8_t tmp)
{
	if(P & _fT)
		tora(tmp);
	else {
		A = (uint8_t)(A | tmp);
		set_nz(A);
	}
}

/* 6280 ********************************************************
 *  PHA Push accumulator
 ***************************************************************/
static inline void pha(void)
{
	clear_t();
	push(A);
}

/* 6280 ********************************************************
 *  PHP Push processor status (flags)
 ***************************************************************/
static inline void php(void)
{
	clear_t();
	compose_p(0,0);
	push(P);
}

/* 6280 ********************************************************
 *  PHX Push index X
 ***************************************************************/
static inline void phx(void)
{
	clear_t();
	push(X);
}

/* 6280 ********************************************************
 *  PHY Push index Y
 ***************************************************************/
static inline void phy(void)
{
	clear_t();
	push(Y);
}

/* 6280 ********************************************************
 *  PLA Pull accumulator
 ***************************************************************/
static inline void pla(void)
{
	clear_t();
	pull(A);
	set_nz(A);
}

/* 6280 ********************************************************
 *  PLP Pull processor status (flags)
 ***************************************************************/
static inline void plp(void)
{
#if H6280_LAZY_FLAGS
	pull(P);
	P |= _fB;
	NZ = ((P & _fN) << 8) |
			((P & _fZ) ^ _fZ);
	check_irq_lines();
#else
	pull(P);
	P |= _fB;
	check_irq_lines();
#endif
}

/* 6280 ********************************************************
 *  PLX Pull index X
 ***************************************************************/
static inline void plx(void)
{
	clear_t();
	pull(X);
	set_nz(X);
}

/* 6280 ********************************************************
 *  PLY Pull index Y
 ***************************************************************/
static inline void ply(void)
{
	clear_t();
	pull(Y);
	set_nz(Y);
}

/* 6280 ********************************************************
 *  RMB Reset memory bit
 ***************************************************************/
static inline uint8_t rmb(int bit, uint8_t tmp)
{
	clear_t();
	tmp &= ~(1<<bit);
	return tmp;
}

/* 6280 ********************************************************
 *  ROL Rotate left
 *  new C <- [7][6][5][4][3][2][1][0] <- C
 ***************************************************************/
static inline uint8_t rol(uint8_t tmp)
{
	clear_t();
	int tmp9 = (tmp << 1) | (P & _fC);
	P = (P & ~_fC) | ((tmp9 >> 8) & _fC);
	tmp = (uint8_t)tmp9;
	set_nz(tmp);
	return tmp;
}

/* 6280 ********************************************************
 *  ROR Rotate right
 *  C -> [7][6][5][4][3][2][1][0] -> new C
 ***************************************************************/
static inline uint8_t ror(uint8_t tmp)
{
	clear_t();
	int tmp9 = tmp | (P & _fC) << 8;
	P = (P & ~_fC) | (tmp & _fC);
	tmp = (uint8_t)(tmp9 >> 1);
	set_nz(tmp);
	return tmp;
}

/* 6280 ********************************************************
 *  RTI Return from interrupt
 *  pull flags, pull PC lo, pull PC hi and increment PC
 ***************************************************************/
static inline void rti(void)
{
#if H6280_LAZY_FLAGS
	pull(P);
	P |= _fB;
	NZ = ((P & _fN) << 8) |
			((P & _fZ) ^ _fZ);
	pull(PCL);
	pull(PCH);
	check_irq_lines();
#else
	pull(P);
	P |= _fB;
	pull(PCL);
	pull(PCH);
	check_irq_lines();
#endif
}

/* 6280 ********************************************************
 *  RTS Return from subroutine
 *  pull PC lo, PC hi and increment PC
 ***************************************************************/
static inline void rts(void)
{
	clear_t();
	pull(PCL);
	pull(PCH);
	PCW++;
}

/* 6280 ********************************************************
 *  SAX Swap accumulator and index X
 ***************************************************************/
static inline void sax(void)
{
	clear_t();
	uint8_t tmp = X;
	X = A;
	A = tmp;
}

/* 6280 ********************************************************
 *  SAY Swap accumulator and index Y
 ***************************************************************/
static inline void say(void)
{
	clear_t();
	uint8_t tmp = Y;
	Y = A;
	A = tmp;
}

/* 6280 ********************************************************
 *  SBC Subtract with carry
 ***************************************************************/
static inline void tsbc(uint8_t tmp)
{
	clear_t();
	int tflagtemp = rd_tfl();
	if (P & _fD)
	{
		int c = (P & _fC) ^ _fC;
		int sum = tflagtemp - tmp -c;
		int lo = (tflagtemp & 0x0f) - (tmp & 0x0f) - c;
		int hi = (tflagtemp & 0xf0) - (tmp & 0xf0);
		P &= ~_fC;
		if (lo & 0xf0)
			lo -= 6;
		if (lo & 0x80)
			hi -= 0x10;
		if (hi & 0x0f00)
			hi -= 0x60;
		if ((sum & 0xff00) == 0)
			P |= _fC;
		tflagtemp = (lo & 0x0f) + (hi & 0xf0);
		h6280_cycles(1);
	}
	else
	{
		int c = (P & _fC) ^ _fC;
		int sum = tflagtemp - tmp - c;
		P &= ~(_fV | _fC);
		if ((tflagtemp^tmp) & (tflagtemp^sum) & _fN)
			P |= _fV;
		if ((sum & 0xff00) == 0)
			P |= _fC;
		tflagtemp = (uint8_t) sum;
	}
	set_nz(tflagtemp);
	wb_eaz(tflagtemp);
	h6280_cycles(3);
}

static inline void sbc(uint8_t tmp)
{
	if(P & _fT)
		tsbc(tmp);
	else {
		if (P & _fD)
		{
			int c = (P & _fC) ^ _fC;
			int sum = A - tmp - c;
			int lo = (A & 0x0f) - (tmp & 0x0f) - c;
			int hi = (A & 0xf0) - (tmp & 0xf0);
			P &= ~_fC;
			if (lo & 0xf0)
				lo -= 6;
			if (lo & 0x80)
				hi -= 0x10;
			if (hi & 0x0f00)
				hi -= 0x60;
			if ((sum & 0xff00) == 0)
				P |= _fC;
			A = (lo & 0x0f) + (hi & 0xf0);
			h6280_cycles(1);
		}
		else
		{
			int c = (P & _fC) ^ _fC;
			int sum = A - tmp - c;
			P &= ~(_fV | _fC);
			if ((A^tmp) & (A^sum) & _fN)
				P |= _fV;
			if ((sum & 0xff00) == 0)
				P |= _fC;
			A = (uint8_t) sum;
		}
		set_nz(A);
	}
}

